              if (idx < 64)
                {
                  s_first[idx] = s_raw[i];
                }

              if (a > peak) peak = a;
              sq += (uint64_t)a * (uint64_t)a;
              if (a != 0) nonzero++;
              if (a > 2000) spike++;
              ph_zero[idx & 7] += (a == 0) ? 1 : 0;
              ph_cnt[idx & 7]++;
