      for (i = 0; i < 8; i++)
        {
          printf("p%u=%u%% ", (unsigned)i,
                 (unsigned)(ph_cnt[i] ? ph_zero[i] * 100 / ph_cnt[i] : 0));
        }
      printf("\n");
      return 0;
    }
