static bool es7210_is_tdm_mode(audio_codec_es7210_t *codec)
{
    uint16_t mic_num = 0;
    for (int i = ES7210_INPUT_MIC1; i <= ES7210_INPUT_MIC4; i = i << 1) {
        if (codec->mic_select & i) {
