int hal_i2s_read_slot(void *buf, uint32_t bytes, int slot)
{
    uint32_t want_samp = bytes / 2;
    uint32_t got = 0;
    uint32_t flight = 0;      /* 在途 apb 数 */
    int cur = 0;              /* 当前等待的 apb 索引 */

    /* 提交第一个 apb */
    flight += submit_rx(buf, chunk, slot, 0);   // ctx[0]
    /* 提交第二个 apb（流水线，不等） */
    if (got + flight < want_samp) flight += submit_rx(buf, chunk, slot, 1);  // ctx[1]

    while (got < want_samp) {
        /* 等 cur 完成 */
        wait sem[cur];
        got += g_rx_ctx[cur].got;
        flight--;
        /* 补提交新 apb（复用 cur 的 ctx） */
        if (got + flight < want_samp) {
            submit_rx(buf + got*2, chunk, slot, cur);   // ctx[cur] 复用
            flight++;
        }
        cur = 1 - cur;   // 切到另一个
    }
    ...
}
```

