**提交函数**：
```c
static int hal_i2s_rx_submit(FAR int16_t *dst, uint32_t nsamp, int slot, int idx)
{
  struct audio_buf_desc_s desc;
  FAR struct ap_buffer_s *apb = NULL;
  uint32_t want = nsamp * 4;   /* 立体声流字节（2槽×16bit）*/
  int ret;

  if (want > 4095) want = 4095;   /* DMA 上限 */
  memset(&desc, 0, sizeof(desc));
  desc.numbytes = want;
  desc.u.pbuffer = &apb;
  ret = apb_alloc(&desc);
  if (ret < 0) return ret;

  g_rx_ctx[idx].dst = dst;
  g_rx_ctx[idx].slot = slot;
  g_rx_ctx[idx].got = 0;
  g_rx_ctx[idx].done = &g_rx_done_sem[idx];

  apb->nbytes = want;
  apb->curbyte = 0;
  ret = g_dev->ops->i2s_receive(g_dev, apb, hal_i2s_rx_cb, &g_rx_ctx[idx], SEC2TICK(3));
  if (ret < 0) { apb_free(apb); return ret; }
  return 0;
}
```

**注意**：want = nsamp*4（2 槽立体声），cap 4095 → nsamp ≤ 1023。nsamp=500 → want=2000 ✓。

**want 必须对齐帧（4B）**：nsamp*4 天然 4 对齐 ✓。

hal_i2s_read_slot 主循环：
```c
int hal_i2s_read_slot(void *buf, uint32_t bytes, int slot)
{
  FAR int16_t *p = buf;
  uint32_t want_samp = bytes / 2;
  uint32_t got = 0;
  uint32_t half;
  int cur = 0;
  int flight = 0;

  if (want_samp == 0) return 0;
  half = (want_samp + 1) / 2;         /* 每 apb 采样数 */
  if (half > 1023) half = 1023;       /* DMA 上限 */

  /* 流水线启动：先提交 2 个（如果 half*2 覆盖 want_samp；否则循环补） */
  while (got < want_samp && flight < 2)
    {
      uint32_t this = MIN(half, want_samp - got);
      if (hal_i2s_rx_submit(p + got*2, this, slot, flight) < 0) break;
      flight++;
