/****************************************************************************
 * 内部：异步提交一个 RX apb（不等待完成）
 *
 * 官方驱动 i2s_receive 把 apb 加入 rx.pend 队列；DMA 完成一个后，ISR
 * （i2s_rx_schedule → i2s_rxdma_start）自动接续 pend 队列下一个 →
 * 只要保持 ≥2 个 apb 在途，RX DMA 永不停止（仿 TX 连续输出）。
 *
 * ctx 复用规则：提交前该 idx 的上一个 apb 必须已完成（其回调 sem_post
 * 是最后一步）——调用方保证。
 ****************************************************************************/

static int hal_i2s_rx_submit(FAR int16_t *dst, uint32_t nsamp,
                             int slot, int idx)
{
  struct audio_buf_desc_s desc;
  FAR struct ap_buffer_s *apb = NULL;
  uint32_t want;
  int ret;

  /* 立体声 2 槽 × 16bit：单声道 nsamp → 流 4×nsamp 字节；DMA 上限 4095 */

  want = nsamp * 4;
  if (want > 4092)
    {
      want = 4092;   /* 4 字节对齐的 DMA 上限（4095 向下取整） */
    }

  memset(&desc, 0, sizeof(desc));
  desc.numbytes = want;
  desc.u.pbuffer = &apb;
  ret = apb_alloc(&desc);
  if (ret < 0)
    {
      return ret;
    }

  g_rx_ctx[idx].dst = dst;
  g_rx_ctx[idx].slot = slot;
  g_rx_ctx[idx].got = 0;
  g_rx_ctx[idx].done = &g_rx_done_sem[idx];

  apb->nbytes = want;
  apb->curbyte = 0;
  ret = g_dev->ops->i2s_receive(g_dev, apb, hal_i2s_rx_cb,
                                &g_rx_ctx[idx], SEC2TICK(3));
  if (ret < 0)
    {
      /* 未入队：释放我们的引用 */

      apb_free(apb);
      return ret;
    }

  return 0;
}

