```c
int hal_i2s_read_slot(void *buf, uint32_t bytes, int slot)
{
  FAR int16_t *p = (FAR int16_t *)buf;
  uint32_t want_samp = bytes / 2;
  uint32_t got = 0;
  uint32_t submitted = 0;
  uint32_t half;
  int cur = 0;
  int flight = 0;

  if (want_samp == 0)
    {
      return 0;
    }

  /* 排空残留完成信号量（防上一次超时/延迟回调的残留 post） */

  while (nxsem_trywait(&g_rx_done_sem[0]) == 0);
  while (nxsem_trywait(&g_rx_done_sem[1]) == 0);

  half = (want_samp + 1) / 2;
  if (half > 1023)
    {
      half = 1023;
    }

  /* 流水线预提交（最多 2 个在途；每个 apb 收独立区间，互不重叠） */

  while (flight < 2 && submitted < want_samp)
    {
      uint32_t this = MIN(half, want_samp - submitted);

      if (hal_i2s_rx_submit(p + submitted * 2, this, slot, flight) < 0)
        {
          break;
        }

      submitted += this;
      flight++;
    }

  if (flight == 0)
    {
      return 0;
    }

  /* 主循环：等完成 → 提取 → 若仍有未提交区间则补提交 */

  while (got < want_samp)
    {
      if (nxsem_tickwait(&g_rx_done_sem[cur], SEC2TICK(3)) < 0)
        {
          printf("[I2S] RX 超时! got=%u/%u flight=%d TX_CONF=0x%08x "
                 "RX_CONF=0x%08x RXEOF=0x%08x\n",
                 (unsigned)got, (unsigned)want_samp, flight,
                 (unsigned)getreg32(I2S_TX_CONF_REG(0)),
                 (unsigned)getreg32(I2S_RX_CONF_REG(0)),
                 (unsigned)getreg32(I2S_RXEOF_NUM_REG(0)));
          break;
        }

      got += g_rx_ctx[cur].got;
      flight--;

      if (submitted < want_samp)
        {
          uint32_t this = MIN(half, want_samp - submitted);

          if (hal_i2s_rx_submit(p + submitted * 2, this, slot, cur) == 0)
            {
              submitted += this;
              flight++;
            }
        }

      cur = 1 - cur;
    }

  /* 清理：等待仍在途的 apb 完成（防延迟回调写调用者缓冲/ctx） */

  while (flight > 0)
    {
      if (nxsem_tickwait(&g_rx_done_sem[cur], SEC2TICK(1)) < 0)
        {
          break;
        }

      flight--;
      cur = 1 - cur;
    }

  return (int)(got * 2);
}
```

**关键修复**：
1. **submitted 独立跟踪**（不依赖 got）→ 每个 apb 区间独立，无重叠
2. **read_slot 开头排空 sem**（防残留 post 误导计数）
3. **flight==0 保护**（提交全失败直接返回 0）

**还有一个隐患：主循环超时后，flight 里可能还有未完成的 apb**（超时说明某个 sem 没等到）。清理循环等它们（各 1s）。**如果清理也超时（延迟回调）→ 返回 got*2，回调稍后写 p+submitted*2（越界？）**——p 是调用者缓冲（chunk48[1000] 或 raw[1024]），submitted ≤ want_samp ≤ bytes/2 → p+submitted*2 ≤ p+bytes ✓ 界内。**但回调写的是 ctx.dst = p+submitted*2（提交时的偏移）→ 界内 ✓。**

