/****************************************************************************
 * 内部：分配 apb 并等待一次异步传输完成
 ****************************************************************************/

static int hal_i2s_apb_transfer(int is_tx, FAR const void *tx_buf,
                                uint32_t tx_bytes,
                                FAR void *rx_buf, uint32_t rx_bytes,
                                int slot, uint32_t timeout_ticks)
{
  struct audio_buf_desc_s desc;
  FAR struct ap_buffer_s *apb = NULL;
  FAR struct hal_i2s_rx_ctx *rctx = &g_rx_ctx;
  uint32_t want;
  int ret;

  if (is_tx)
    {
      want = tx_bytes;
    }
  else
    {
      /* RX：官方驱动收立体声流；单声道请求 nsamp 采样需要 2×nsamp 字 */

      want = rx_bytes * 2;
    }

  /* 官方驱动 RX 单次 ≤ ESP32S3_DMA_BUFLEN_MAX(4095B) */

  if (want > 4095)
    {
      want = 4095;
    }

  memset(&desc, 0, sizeof(desc));
  desc.numbytes = want;
  desc.u.pbuffer = &apb;
  ret = apb_alloc(&desc);
  if (ret < 0)
    {
      return ret;
    }

  if (is_tx)
    {
      memcpy(apb->samp, tx_buf, want);
      apb->nbytes = want;
      apb->curbyte = 0;
      ret = g_dev->ops->i2s_send(g_dev, apb, hal_i2s_tx_cb, NULL,
                                 timeout_ticks);
    }
  else
    {
      rctx->dst = (FAR int16_t *)rx_buf;
      rctx->slot = slot;
      rctx->got = 0;
      apb->nbytes = want;
      apb->curbyte = 0;
      ret = g_dev->ops->i2s_receive(g_dev, apb, hal_i2s_rx_cb, rctx,
                                    timeout_ticks);
    }

  if (ret < 0)
    {
      /* 未入队：释放我们的引用（i2s_send/receive 失败路径官方驱动
       * 可能已 reference，此处至少避免 UAF） */

      apb_free(apb);
      return ret;
    }

  /* 等传输完成。⚠️ 回调里已释放我们的 apb 引用并提取了 RX 数据；
   * 返回后绝不再访问 apb（官方驱动在回调后还会 apb_free 最终释放，
   * 我们若再操作即 UAF）。 */

  if (is_tx)
    {
      if (nxsem_tickwait(&g_tx_done_sem, timeout_ticks) < 0)
        {
          return -ETIMEDOUT;   /* apb 由官方驱动超时路径清理，勿碰 */
        }

      return (int)tx_bytes;
    }
  else
    {
      if (nxsem_tickwait(&g_rx_done_sem, timeout_ticks) < 0)
        {
          /* ⚠️ 2026-08-25 诊断：RX 超时现场——TX_CONF 判读：
           * bit2=TX_START（TX 是否启动）、bit13=TX_STOP_EN（0=时钟保持）、
           * bit27=SIG_LOOPBACK（TX/RX 共享时钟）。 */

          printf("[I2S] RX 超时! TX_CONF=0x%08x RX_CONF=0x%08x "
                 "RXEOF=0x%08x\n",
                 (unsigned)getreg32(I2S_TX_CONF_REG(0)),
                 (unsigned)getreg32(I2S_RX_CONF_REG(0)),
                 (unsigned)getreg32(I2S_RXEOF_NUM_REG(0)));
          return -ETIMEDOUT;
        }

      return (int)(rctx->got * 2);
    }
}

int hal_i2s_write(const void *buf, uint32_t bytes)
{
  uint32_t sent = 0;
  FAR const uint8_t *p = buf;

  while (sent < bytes)
    {
      uint32_t chunk = MIN(bytes - sent, 4095);

      chunk -= (chunk % HAL_FRAME_BYTES);   /* 对齐到帧（4B） */

      if (chunk == 0)
        {
          break;
        }

      if (hal_i2s_apb_transfer(1, p + sent, chunk, NULL, 0, 0,
                               SEC2TICK(5)) < 0)
        {
          break;
        }

      sent += chunk;
    }

  return (sent > 0) ? (int)sent : -EIO;
}

int hal_i2s_read(void *buf, uint32_t bytes)
{
  return hal_i2s_read_slot(buf, bytes, 0);
}

int hal_i2s_read_slot(void *buf, uint32_t bytes, int slot)
{
  uint32_t got = 0;
  FAR uint8_t *p = buf;
  uint32_t want_samp = bytes / 2;

  /* 官方 RX 单次 ≤4095B（立体声流）→ 每块最多 1023 个单声道采样。
   * 串行循环收满：单次调用内 apb 之间处理极快（< RX FIFO 64B 溢出
   * 时间 0.67ms）→ 不丢数据。调用方（ai_voice_stream_record）块间
   * 处理也需保持 < 0.67ms（勿在块间做网络上传）。 */

  while (got < want_samp)
    {
      uint32_t chunk_samp = MIN(want_samp - got, 1023);
      int r = hal_i2s_apb_transfer(0, NULL, 0, p + got * 2,
                                   chunk_samp * 2, slot, SEC2TICK(3));

      if (r <= 0)
        {
          break;
        }

      got += (uint32_t)r / 2;
    }

  return (int)(got * 2);
}

int hal_i2s_rx_set_channel(int slot)
{
  /* 官方驱动 RX 恒为 2 槽立体声；槽选择在 read_slot 完成 */

  (void)slot;
  return 0;
}
