  while (got < want_samp)
    {
      uint32_t chunk_samp = MIN(want_samp - got, 1023);
      int r = hal_i2s_apb_transfer(0, NULL, 0, p + got * 2,
                                   chunk_samp * 2, slot, SEC2TICK(3));

      if (r <= 0)
        {
          break;
        }

      got += (uint32_t)r / 2;
    }

  /* 3. 预提交下一轮预读（DMA 提前开始收，跨调用连续不溢出） */

  if (got > 0)
    {
      hal_i2s_rx_prefetch(slot);
    }

  return (int)(got * 2);
}", "old_string": "int hal_i2s_read_slot(void *buf, uint32_t bytes, int slot)
{
  uint32_t got = 0;
  FAR uint8_t *p = buf;
  uint32_t want_samp = bytes / 2;

  /* 官方 RX 单次 ≤4095B（立体声流）→ 每块最多 1023 个单声道采样。
   * 串行循环收满：单次调用内 apb 之间处理极快（< RX FIFO 64B 溢出
   * 时间 0.67ms）→ 不丢数据。调用方（ai_voice_stream_record）块间
   * 处理也需保持 < 0.67ms（勿在块间做网络上传）。 */

  while (got < want_samp)
    {
      uint32_t chunk_samp = MIN(want_samp - got, 1023);
      int r = hal_i2s_apb_transfer(0, NULL, 0, p + got * 2,
                                   chunk_samp * 2, slot, SEC2TICK(3));

      if (r <= 0)
        {
          break;
        }

      got += (uint32_t)r / 2;
    }

  return (int)(got * 2);
}"}

